sys_script_include.script:
var CheckTrainingDate = Class.create();
CheckTrainingDate.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    checkDateConflict: function() {
        var curso = this.getParameter('sysparm_curso');
        var dataTreinamento = this.getParameter('sysparm_data');

        if (!curso || !dataTreinamento) {
            return "error";
        }

        var gr = new GlideRecord('x_1593183_traini_0_training_schedules'); // Substitua pelo nome correto da tabela
        gr.addQuery('course', curso);
        gr.addQuery('training_date', dataTreinamento);
        gr.query();

        if (gr.next()) {
            return "conflict"; 
        }

        return "ok"; // Nenhum conflito encontrado
    }
});
